export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const original = clone(d.nodes),
    result = {};
  const visit = (id) => {
    if (Object.hasOwn(result, id)) return;
    result[id] = clone(d.nodes[id]);
    for (const next of d.nodes[id].edges) visit(next);
  };
  visit(d.root);
  for (const e of d.edits) result[e.id].value = clone(e.value);
  return { original, clone: result };
}

